/* ==========================================================================
   TRANSCENDENTAL – Script do site
   Site de página única (SPA) em JavaScript puro, com rotas por "hash":
   #/  #/sobre  #/equipa  #/servicos  #/servico  #/precos  #/contacto

   Índice
   1. Contactos e imagens
   2. Funções auxiliares que criam blocos de HTML
   3. Dados dos serviços e dos clientes
   4. Dados dos preços
   5. Funções da página de preços
   6. Dados da equipa e formulário de contacto
   7. Páginas do site
   8. Navegação (router)
   ========================================================================== */


/* ==========================================================================
   1. CONTACTOS E IMAGENS
   ========================================================================== */

// Ligação do WhatsApp e email da empresa
const WHATSAPP = 'https://wa.me/244941391824';
const EMAIL = 'geral@transcendental.ao';

// Fotografias (em base64) da equipa e dos modelos: 0 a 3 = equipa, 4 a 7 = modelos
const FOTOS_EQUIPA = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];

// Imagens grandes usadas nas páginas (secções com texto + imagem)
const IMAGENS_FUNDO = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];


/* ==========================================================================
   2. FUNÇÕES AUXILIARES QUE CRIAM BLOCOS DE HTML
   Cada função devolve uma string de HTML que é inserida nas páginas.
   ========================================================================== */

// Caixa de imagem reservada (placeholder). "modificador" é uma classe extra opcional
const criarPlaceholder = (modificador, legenda) =>
    `<div class="placeholder ${modificador}">${legenda || ''}</div>`;

// Imagem do site. "fonte" é o endereço da imagem; "textoAlternativo" descreve-a
const criarImagem = (fonte, textoAlternativo) =>
    `<img class="imagem" src="${fonte}" alt="${textoAlternativo || ''}">`;

// Faixa roxa de título no topo das páginas internas (ex.: "Início / Sobre nós")
const criarFaixaTitulo = (titulo, caminho) =>
    `<div class="faixa-titulo"><div class="container"><h2>${titulo}</h2><span>Início / ${caminho || titulo}</span></div></div>`;

// Cabeçalho centrado de uma secção: etiqueta + título + subtítulo opcional
const criarCabecalhoSecao = (etiqueta, titulo, subtitulo) =>
    `<div class="cabecalho-secao"><i class="etiqueta">${etiqueta}</i><h2 class="titulo-secao">${titulo}</h2>${subtitulo ? `<p style="margin-top:12px">${subtitulo}</p>` : ''}</div>`;

// Destaque com ícone ✓, título e descrição
const criarDestaque = (titulo, descricao) =>
    `<div class="destaque"><span class="icone">✓</span><div><h3>${titulo}</h3><p>${descricao}</p></div></div>`;

// Caixas com 3 passos (usado em "Como trabalhamos"). "lista" é um array de [título, texto]
const criarPassos = lista =>
    `<div class="passos">${lista.map(passo => `<div><h3>${passo[0]}</h3><p>${passo[1]}</p></div>`).join('')}</div>`;


/* ==========================================================================
   3. DADOS DOS SERVIÇOS E DOS CLIENTES
   ========================================================================== */

// Os 8 serviços da agência: [nome, descrição]
const SERVICOS = [
    ["Design de marcas", "Logótipo e identidade visual completa. Prazo: 15 a 30 dias."],
    ["Design publicitário", "Cartazes, flyers, banners, convites e catálogos. Prazo: 3 a 15 dias."],
    ["Marketing digital", "Gestão de redes sociais, estratégia e anúncios pagos. Prazo: 5 a 15 dias."],
    ["Web design", "Sites e lojas online, com domínio e hospedagem. Prazo: 15 a 30 dias."],
    ["Conteúdo digital", "Artes, vídeos curtos e artigos para redes e site. Prazo: 5 a 30 dias."],
    ["Vídeo institucional", "Gravação e edição de vídeos de empresas e eventos. Prazo: 5 a 15 dias."],
    ["Livestreaming", "Transmissão ao vivo de eventos, cultos e conferências, no momento do evento."],
    ["Impressão e produção gráfica", "Lonas, vinil, fardamento, brindes, carimbos e blocos de factura. Prazo sob demanda."]
];

// Grelha com os 8 serviços (cada um é uma ligação para a página de serviços)
const criarGrelhaServicos = () =>
    `<div class="grelha-servicos">${SERVICOS.map(servico => `<a href="#/servicos" class="destaque"><span class="icone claro">✦</span><div><h3>${servico[0]}</h3><p>${servico[1]}</p></div></a>`).join('')}</div>`;

// Lista de clientes que já trabalharam com a agência
const CLIENTES = ["UJES", "FCA-UJES", "FEc-UJES", "FMV-UJES", "Governo Provincial do Huambo", "Governo Provincial do Cuanza Sul", "ISUPE Ekuikui II", "ISCED Huambo", "RETFOP", "Banco Nacional de Angola", "Primeira Igreja Baptista do Huambo", "Afrodourado", "FUNDECIT", "Cash Peritus", "Kalvec Lda", "DJRCASS", "Centro Excelência", "Clínica Tchissola", "Conecta Eventos", "Traços Multimédia", "Valor Sublime", "Silva Moveleira", "Fazenda Escola", "TecnAgro", "SmartAgro", "Casa Rural", "MACA Huambo", "ACAVALIR Lda", "ALAVITA Lda"];

// Secção "Quem já trabalhou connosco" (clientes em forma de "chips")
const criarSecaoClientes = () =>
    `<section class="fundo-claro">${criarCabecalhoSecao("Clientes", "Quem já trabalhou connosco", "Mais de 300 clientes atendidos desde 2017.")}<div class="container chips">${CLIENTES.map(cliente => `<span>${cliente}</span>`).join('')}</div></section>`;

// Secção roxa com os números da empresa
const criarSecaoEstatisticas = () =>
    `<section class="fundo-roxo" style="padding:44px 0"><div class="container estatisticas">${[["+300", "Clientes atendidos"], ["+700", "Projectos feitos"], ["+30", "Vídeos e eventos cobertos"], ["2017", "Ano de fundação"]].map(item => `<div><b>${item[0]}</b><small>${item[1]}</small></div>`).join('')}</div></section>`;

// Secção "Trabalhos recentes" (6 caixas vazias à espera de imagens do portfólio)
const criarSecaoPortfolio = () =>
    `<section>${criarCabecalhoSecao("Portfólio", "Trabalhos recentes")}<div class="container grelha-3">${[0, 1, 2, 3, 4, 5].map(() => '<div class="placeholder vazio"></div>').join('')}</div></section>`;

// Secção "Porquê nós": imagem + os três critérios (conceito, estética, funcionalidade)
const criarSecaoPorqueNos = () =>
    `<section><div class="container duas-colunas">${criarImagem(IMAGENS_FUNDO[2])}<div><i class="etiqueta">Porquê nós</i><h2 class="titulo-secao">Três critérios em cada projecto</h2><p class="texto-suave" style="margin:14px 0 22px">Antes de entregar, cada peça passa por três perguntas.</p>${[["Conceito", "Há uma ideia clara por trás? Primeiro percebemos o negócio, depois desenhamos."], ["Estética", "Está bonito e coerente com a marca, do logótipo ao fardamento?"], ["Funcionalidade", "Serve para vender, informar ou identificar? Se não serve, não está pronto."]].map(criterio => `<div class="destaque" style="margin:14px 0"><span class="icone pequeno">✓</span><div><h3 style="font-size:16px">${criterio[0]}</h3><p>${criterio[1]}</p></div></div>`).join('')}</div></div></section>`;

// Secção final "O teu próximo grande passo" com botões de orçamento e WhatsApp
const criarSecaoChamadaAcao = () =>
    `<section><div class="container duas-colunas"><div><i class="etiqueta">Começa agora</i><h2 class="titulo-secao">O teu próximo grande passo</h2><p class="texto-suave" style="margin:14px 0 22px">Conta-nos o que o teu negócio precisa e respondemos com uma proposta.</p><a class="botao" href="#/contacto">Pedir orçamento</a> <a class="botao claro" target="_blank" rel="noopener" href="${WHATSAPP}">WhatsApp</a></div>${criarImagem(IMAGENS_FUNDO[3])}</div></section>`;

// Secção de perguntas frequentes. Clicar numa pergunta mostra/esconde a resposta
// (a primeira pergunta começa aberta; o índice "i" é 0 para ela)
const criarSecaoFaq = () =>
    `<section><div class="container duas-colunas" style="align-items:start"><div><h2 class="titulo-secao titulo-menor" style="margin-bottom:24px">Perguntas frequentes</h2>${[["Quanto tempo leva uma identidade visual?", "Entre 15 e 30 dias. O processo tem fases (naming, logótipo e paleta, aplicação), cada uma de 1 a 5 dias, conforme a complexidade."], ["Como funciona o pagamento?", "Pedimos um adiantamento mínimo de 50%. Serviços abaixo de 15 000 Kz são pagos antes de começarmos."], ["Quantas alterações posso pedir?", "Depende do pacote: de 1 alteração no Light até 5 no VIP, sempre antes da aprovação final."], ["A impressão está incluída?", "Não. Impressão e produção de vídeo são orçadas à parte, sob consulta."], ["Quem gere as redes sociais?", "Nos pacotes de gestão de marketing, nós. O conteúdo é aprovado por ti antes de publicar."], ["Têm escritório?", "Somos uma agência digital, sem escritório fixo. Atendemos por WhatsApp e email e combinamos reuniões no Huambo."]].map((item, i) => `<div><div class="pergunta" onclick="this.nextElementSibling.classList.toggle('aberto')">${item[0]}<span>${i ? '⊖' : '⊕'}</span></div><div class="resposta ${i ? '' : 'aberto'}">${item[1]}</div></div>`).join('')}</div>${criarImagem(IMAGENS_FUNDO[1])}</div></section>`;


